 69	function inspectSourceLexically(source) {
 70		const withoutComments = source
 71			.replace(/\/\*[\s\S]*?\*\//g, " ")
 72			.replace(/(^|\s|;)\/\/.*$/gm, "$1 ");
 73		const edges = [];
 74		for (const pattern of [
 75			/(?:import|export)\s+(?:type\s+)?(?:[\s\S]*?\sfrom\s*)?["']([^"']+)["']/g,
 76			/\bimport\s*\(\s*["']([^"']+)["']\s*\)/g,
 77			/\brequire\s*\(\s*["']([^"']+)["']\s*\)/g,
 78		]) {
 79			for (const match of withoutComments.matchAll(pattern)) {
 80				edges.push({ specifier: match[1], kind: "lexical" });
 81			}
 82		}
 83		const nonLiteralCalls = [
 84			...withoutComments.matchAll(/\bimport\s*\(\s*(?!["'])/g),
 85			...withoutComments.matchAll(/\brequire\s*\(\s*(?!["'])/g),
 86		].map(() => "dynamic");
 87		return { edges, nonLiteralCalls };
 88	}
