 90	function inspectCompilerSourceFile(sourceFile) {
 91		const edges = [];
 92		const nonLiteralCalls = [];
 93	
 94		function visit(node) {
 95			if (ast.isImportDeclaration(node) || ast.isExportDeclaration(node)) {
 96				const specifier = moduleSpecifier(node.moduleSpecifier);
 97				if (specifier) edges.push({ specifier, kind: "import" });
 98			}
 99			if (ast.isImportEqualsDeclaration(node)) {
100				const reference = node.moduleReference;
101				if (ast.isExternalModuleReference(reference)) {
102					const specifier = moduleSpecifier(reference.expression);
103					if (specifier) edges.push({ specifier, kind: "import-equals" });
104				}
105			}
106			if (ast.isCallExpression(node)) {
107				const expression = node.expression;
108				const isImportCall = expression.kind === ast.SyntaxKind.ImportKeyword;
109				const isRequireCall =
110					ast.isIdentifier(expression) && expression.text === "require";
111				if (isImportCall || isRequireCall) {
112					const argument = node.arguments[0];
113					const specifier = moduleSpecifier(argument);
114					if (specifier)
115						edges.push({
116							specifier,
117							kind: isImportCall ? "import()" : "require",
118						});
119					else nonLiteralCalls.push(isImportCall ? "import()" : "require");
120				}
121			}
122			node.forEachChild(visit);
123		}
