    58	export async function compareDirectoryTrees(expectedRoot, actualRoot) {
    59		const expectedFiles = new Map(
    60			(await collectFiles(expectedRoot)).map((path) => [
    61				relativePath(expectedRoot, path),
    62				path,
    63			]),
    64		);
    65		const actualFiles = new Map(
    66			(await collectFiles(actualRoot)).map((path) => [
    67				relativePath(actualRoot, path),
    68				path,
    69			]),
    70		);
    71		const differences = [];
    72		const paths = new Set([...expectedFiles.keys(), ...actualFiles.keys()]);
    73	
    74		for (const path of [...paths].sort((left, right) =>
    75			left.localeCompare(right),
    76		)) {
    77			const expectedPath = expectedFiles.get(path);
    78			const actualPath = actualFiles.get(path);
    79			if (!expectedPath) {
    80				differences.push(`unexpected generated file: ${path}`);
    81				continue;
    82			}
    83			if (!actualPath) {
    84				differences.push(`missing generated file: ${path}`);
    85				continue;
    86			}
    87	
    88			const [expected, actual] = await Promise.all([
    89				readFile(expectedPath),
    90				readFile(actualPath),
    91			]);
    92			if (!expected.equals(actual)) {
    93				differences.push(`generated file differs: ${path}`);
    94			}
    95		}
    96	
    97		return differences;
    98	}
